import React, { useState } from "react";

export default function RenderDemo() {
  const [count, setCount] = useState(0);

  // This console.log represents the "Render Phase"
  // It runs every time the component is asked "what should you look like?"
  console.log("Render Phase: Evaluating the component... Count is", count);

  return (
    <div>
      <h2>Count: {count}</h2>
      {/* 1. The Trigger */}
      <button onClick={() => setCount(c => c + 1)}>Trigger Update</button>
      <button onClick={() => setCount(0)}>Set to 0 (Try clicking when already 0)</button>
    </div>
  );
}
